    static int sum(int[] a) {
        int s = 0;
        for (int v : a) {
            s += v;
        }
        return s;
    }

    public static void main(String[] args) {
        try {
            check("tally(60, seed 7)", "[14, 6, 8, 16, 13, 3]",
                    java.util.Arrays.toString(DiceFaceTally.tally(60, 7L)));
            check("tally(600, seed 7)", "[108, 108, 91, 105, 98, 90]",
                    java.util.Arrays.toString(DiceFaceTally.tally(600, 7L)));
