/**
 * Seeded dice statistics: how often each face of a six-sided die comes up.
 */
public class DiceFaceTally {

    public static int[] tally(int rolls, long seed) {
        java.util.Random rng = new java.util.Random(seed);
        int[] counts = new int[6];
        for (int i = 0; i < rolls; i++) {
            counts[rng.nextInt(6)]++;
        }
        return counts;
    }

    public static int mostCommonFace(int[] counts) {
        int best = 0;
        for (int i = 1; i < counts.length; i++) {
            if (counts[i] > counts[best]) {
                best = i;
            }
        }
        return best + 1;
    }
}
